dence\\": 1.0\\n    },\\n    {\\n      \\"canonical_term\\": \\"Республиканская партия США\\",\\n      \\"surface_forms\\": [\\n        \\"республиканцы\\",\\n        \\"Republicans\\",\\n        \\"Республиканская партия США\\",\\n        \\"Republican Party\\"\\n      ],\\n      \\"negative_surface_forms\\": [\\"Демократическая партия США\\"],\\n      \\"canonical_description\\": \\"One of the two major contemporary political parties in the United States, traditionally associated with conservative and right-leaning policies.\\",\\n      \\"term_type\\": \\"entity\\",\\n      \\"confidence\\": 1.0\\n    },\\n    {\\n      \\"canonical_term\\": \\"Демократическая партия США\\",\\n      \\"surface_forms\\": [\\n        \\"демократы\\",\\n        \\"Democrats\\",\\n        \\"Демократическая партия США\\",\\n        \\"Democratic Party\\"\\n      ],\\n      \\"negative_surface_forms\\": [\\"Республиканская партия США\\"],\\n      \\"canonical_description\\": \\"One of the two major contemporary political parties in the United States, traditionally associated with liberal and left-leaning policies.\\",\\n      \\"term_type\\": \\"entity\\",\\n      \\"confidence\\": 1.0\\n    },\\n    {\\n      \\"canonical_term\\": \\"НАТО\\",\\n      \\"surface_forms\\": [\\n        \\"НАТО\\",\\n        \\"NATO\\",\\n        \\"North Atlantic Treaty Organization\\"\\n      ],\\n      \\"negative_surface_forms\\": [\\"ООН\\", \\"UN\\"],\\n      \\"canonical_description\\": \\"An intergovernmental military alliance between 32 North American and European countries, established for mutual defense and security cooperation.\\",\\n      \\"term_type\\": \\"entity\\",\\n      \\"confidence\\": 1.0\\n    },\\n    {\\n      \\"canonical_term\\": \\"Северный морской путь\\",\\n      \\"surface_forms\\": [\\n        \\"Северный морской путь\\",\\n        \\"Northern Sea Route\\"\\n      ],\\n      \\"negative_surface_forms\\": [\\"Южный морской путь\\"],\\n      \\"canonical_description\\": \\"